/**
 * surfaceTypes — the schema of `live-surfaces.json`, the DATA that tells the
 * 3D scene how to show every part's live state.
 *
 * Why this is a data file and not code
 * ------------------------------------
 * The 2D canvas already renders every part from a web component whose
 * properties the simulation writes (a sketch prints to the LCD → the part's
 * attach code sets `el.characters`; an LED's PWM duty → `el.brightness`;
 * a servo's command → `el.angle`). The 3D view must show the SAME state, not
 * a second guess at it — so it reads the very same property off the very same
 * element, and this file only says WHICH property means what and WHERE on the
 * body it belongs.
 *
 * Consequences that matter:
 *   • adding a part to the 3D view is adding an entry, not editing renderers;
 *   • a part with no entry is not faked — it renders as geometry only, and the
 *     `pnpm verify:3d-live` gate (Wireup) fails until the table covers it;
 *   • every source property is machine-checked against the vendored part
 *     source / `@wokwi/elements` typings by that same gate, so a renamed
 *     property is a build failure rather than a silently dead display.
 *
 * Anchors are expressed in one of two frames (see `LiveAnchor`), and the gate
 * refuses a `spec` anchor on a key whose 3D asset is not generated from that
 * spec — the frame is only trustworthy where the geometry provably comes from
 * the spec.
 */

/** One surface the 3D view can show for a part. */
export interface LiveSurface {
  /** Stable id, unique within the part (also the diagnostics label). */
  id: string;
  kind: SurfaceKind;
  anchor: LiveAnchor;
  /** How to read display-style signals (text grid / pixels / segments / bars). */
  display?: DisplaySource;
  /** How to read an emissive (light-emitting) signal. */
  emissive?: EmissiveSource;
  /** How to move a node from a live value (servo horn, knob, lever, button). */
  motion?: MotionSource;
  /** How to read a numeric readout (sensors, motor RPM). */
  readout?: ReadoutSource;
  style?: SurfaceStyle;
}

/**
 * The version of this schema, mirrored from Wireup's
 * `src/modules/simulation/live-surfaces.ts` (`LIVE_SURFACES_VERSION`).
 *
 * `/live-surfaces.json` is generated by Wireup and consumed here, so a skew
 * between the two is a real failure mode: the file's `version` is compared with
 * this constant on intake, and Wireup's `pnpm verify:3d-live` asserts the two
 * numbers are equal — a schema change on either side fails there, not in
 * production.
 */
export const LIVE_SURFACE_SCHEMA_VERSION = 1;

/** Every surface kind the renderer understands. A manifest entry whose kind is
 *  not in this list is dropped on intake and reported (never half-rendered). */
export const SURFACE_KINDS: readonly SurfaceKind[] = [
  'text-grid',
  'image-data',
  'canvas',
  'rgb-pixels',
  'segments',
  'bar-graph',
  'emissive',
  'motion',
  'readout',
];

export type SurfaceKind =
  /** Character display (HD44780 LCD): the same glyph ROM the 2D element uses. */
  | 'text-grid'
  /** 1-bit framebuffer exposed as an `ImageData` (SSD1306 and friends). */
  | 'image-data'
  /** A real `<canvas>` inside the element (ILI9341, ePaper) — copied per frame. */
  | 'canvas'
  /** Addressable RGB pixels (WS2812B single / ring / matrix / strip). */
  | 'rgb-pixels'
  /** 7-segment digits. */
  | 'segments'
  /** LED bar graph. */
  | 'bar-graph'
  /** Light emission on the body itself (LEDs, RGB LEDs, indicator lamps). */
  | 'emissive'
  /** A moving part driven by a live value. */
  | 'motion'
  /** A floating measurement plaque (sensors, motors). */
  | 'readout';

/**
 * Where a surface sits on the part.
 *
 * `frame: 'spec'` uses the exact millimetre coordinates of the CAD spec
 * (`/cad-catalog.json`, Wireup's registry) — trustworthy only for keys whose
 * 3D asset is generated from that same spec (`generated: true` in the models
 * manifest); the gate enforces that.
 *
 * `frame: 'model'` is resolved against the loaded geometry — a named node
 * first (`node`), then a mesh/material whose feature name matches
 * (`feature`), then the body's bounding box (`top` free). It is the right
 * frame for hand-reviewed GLBs, where the mesh need not match the spec to the
 * millimetre.
 */
export interface LiveAnchor {
  frame: 'spec' | 'model';
  /** CAD feature to attach to: a feature TYPE (`screen`, `led`, `cylinder`,
   *  `potentiometer`, `box`, …) or an exact feature NAME. */
  feature?: string;
  /** Named node in the loaded model (GLB node / parametric assembly group). */
  node?: string;
  /** Prefer the feature's +Y face (a display panel sits ON the glass). */
  face?: 'top' | 'front' | 'center';
  /** Model frame: attach to the body's bounding-box top face (no feature). */
  bodyTop?: boolean;
  /** Extra local offset, in millimetres/degrees, applied after resolution. */
  offsetMm?: [number, number, number];
  rotationDeg?: [number, number, number];
  /** Scale the surface's natural footprint (1 = the anchor's own size). */
  scale?: number;
}

/** Live signals for a display surface, by element property name. */
export interface DisplaySource {
  /** Character buffer property (`characters`) — text-grid only. */
  characters?: string;
  /** Glyph ROM property (`font`); absent → nothing but blocks are drawn. */
  font?: string;
  /** Colon / backlight / cursor companions. */
  colon?: string;
  colonValue?: string;
  colonVisible?: string;
  backlight?: string;
  cursor?: string;
  cursorX?: string;
  cursorY?: string;
  blink?: string;
  /** Grid geometry (cols × rows), for a text grid. */
  cols?: number;
  rows?: number;
  /** `ImageData` property (`imageData`) plus the framebuffer size. */
  imageData?: string;
  width?: number;
  height?: number;
  /** Element canvas property (`canvas`) — a real HTMLCanvasElement. */
  canvas?: string;
  /** Store-backed RGB pixels (neopixel family): `usePartRenderStore.values[id].pixels`. */
  pixels?: boolean;
  /** Pixel layout for `rgb-pixels`. */
  layout?: 'single' | 'strip' | 'ring' | 'matrix';
  /** Index array property (`values`) for segments / bars. */
  values?: string;
  /** Digit-count property (`digits`) for segments. */
  digits?: string;
}

/** How an emissive (light) surface reads its intensity/colour. */
export interface EmissiveSource {
  mode: 'brightness' | 'boolean' | 'rgb255' | 'rgb01' | 'channels' | 'value-fraction';
  /** Property names, in the order the mode needs them
   *  (`rgb255` → [R, G, B]; `channels` → one per `channels` entry). */
  props: string[];
  /** Channel colours for `channels`, as CSS colours. */
  colors?: string[];
  /** Fallback colour when the part has no colour property of its own. */
  color?: string;
  /** Property that carries the emissive's own colour (an LED's `color`, a
   *  CSS colour string) — read live, so a part whose colour the user set
   *  glows in that colour instead of a baked-in guess. */
  colorProp?: string;
  /** Value that counts as "on" for `boolean` (default true). */
  onValue?: unknown;
  /** Max brightness multiplier applied at full scale (default 1). */
  max?: number;
  /** Value span for `value-fraction` (defaults to 0..1). */
  valueRange?: [number, number];
}

/** A live-driven transform on a node / feature. */
export interface MotionSource {
  mode: 'angle' | 'fraction' | 'press' | 'tilt' | 'spin' | 'rotate';
  /** Property the value comes from (`angle`, `value`, `pressed`, …).
   *  `spin` takes [drive, turnsPerSecond]; `rotate` takes an absolute angle. */
  props: string[];
  /** Travel limits: degrees for `angle`, millimetres for `fraction`/`press`. */
  range?: [number, number];
  /** Value range the signal spans (`value` → [0, 1023] for a pot, [0,1] …). */
  valueRange?: [number, number];
  /** Rotation axis for `angle`/`spin`/`rotate` (default `y`). */
  axis?: 'x' | 'y' | 'z';
  /** Invert the direction (a lever that travels against the value). */
  invert?: boolean;
  /** `spin`: the drive value below which the shaft is treated as stopped
   *  (a motor with 2 % duty does not visibly turn). Default 0.02. */
  deadband?: number;
}

/** A floating measurement plaque. */
export interface ReadoutSource {
  rows: ReadoutRow[];
  /** Show the plaque only when the part is selected (default: always). */
  selectedOnly?: boolean;
}

export interface ReadoutRow {
  label: string;
  /** Element property (or store key) holding the value. */
  prop: string;
  unit?: string;
  /** Decimal places (default 0). */
  precision?: number;
}

export interface SurfaceStyle {
  /** Text / glyph colour. */
  textColor?: string;
  /** Panel colour when the display is blank. */
  offColor?: string;
  /** Backlight tint (LCDs). */
  backlightColor?: string;
  /** Lit colour for segments / bars / pixels (CSS colour, or a channel list). */
  onColor?: string;
  /** Unlit segment colour. */
  dimColor?: string;
  /** Pixel glow radius in millimetres for `rgb-pixels`. */
  glowMm?: number;
  /** Plaque text colour. */
  labelColor?: string;
  /** Overall opacity of the surface (1 = opaque). */
  opacity?: number;
}

/** One part's live-surface definition. */
export interface PartLiveSurfaces {
  /** The element tag the 2D canvas instantiates (provenance only). */
  tag?: string;
  /** Human name, for diagnostics. */
  name?: string;
  /** Explicitly: this part has live state but none of it is visible in 3D. */
  visible?: false;
  /** Why it has no visible live state (shown by the verify gate). */
  reason?: string;
  surfaces?: LiveSurface[];
}

export interface LiveSurfaceManifest {
  version: number;
  generatedAt: string;
  /** metadataId → definition. */
  parts: Record<string, PartLiveSurfaces>;
  /** metadataId → why it has no live state at all (registers behaviour, but
   *  its output is purely electrical: gate, shift register, RTC …). */
  noLiveState: Record<string, string>;
}
